/* ============================================================================
   PANEL-01 · Mi Panel (dashboard de inicio)
   ========================================================================== */

.body {
  flex: 1;
  overflow-y: auto;
  padding: 24px 28px 40px;
  background: var(--bw-cold-white); /* spec §2: fondo Cold White */
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-eyebrow);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-calibration-blue);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-title);
  font-weight: 700;
  color: var(--bw-deep-steel);
  letter-spacing: var(--bw-ls-title);
  margin-bottom: 3px;
}

.sub {
  font-size: var(--bw-size-body);
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 600px;
}

/* ── Rejilla de tarjetas (spec §4) ─────────────────────────────────────── */
.grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  max-width: 820px;
}

@media (max-width: 720px) {
  .grid {
    grid-template-columns: 1fr;
  }
}

.card {
  /* El HTML aprobado usa blanco puro; no hay token de blanco en el sistema,
     así que el neutro más claro de la paleta hace de superficie de tarjeta. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 10px; /* radio de tarjeta del HTML aprobado; --bw-radius (3px) es el radio base de controles */
  padding: 18px 20px;
  cursor: pointer;
  transition: box-shadow 0.15s, border-color 0.15s;
  display: flex;
  flex-direction: column;
  gap: 6px;
  text-align: left;
  font-family: inherit;
  color: inherit;
}

.card:hover:not(:disabled) {
  border-color: var(--bw-line-steel-strong);
  /* El HTML aprobado pide una sombra de elevación sin token; --bw-focus-halo
     es la única sombra del sistema y hace el realce de interacción. */
  box-shadow: var(--bw-focus-halo);
}

.card:focus-visible {
  outline: none;
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}

.card:disabled {
  cursor: default;
}

.cardHead {
  display: flex;
  align-items: center;
  gap: 9px;
}

.ico {
  width: 32px;
  height: 32px;
  border-radius: 7px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 17px; /* del HTML aprobado; no hay token de tamaño de icono */
  flex-shrink: 0;
}

.icoBlue {
  background: var(--bw-icon-tint-blue);
  color: var(--bw-calibration-blue);
}

.cardTitle {
  font-family: var(--bw-font-title);
  font-size: var(--bw-size-input); /* 13px, igual que el HTML aprobado */
  font-weight: 700;
  color: var(--bw-deep-steel);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-hint);
}

.num {
  font-family: var(--bw-font-title);
  font-size: 32px; /* display grande del HTML aprobado; no hay token */
  font-weight: 700;
  color: var(--bw-deep-steel);
  line-height: 1;
}

.label {
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.invLine {
  font-size: var(--bw-size-input);
  color: var(--bw-ink-steel);
}

.invLine b {
  color: var(--bw-deep-steel);
  font-weight: 600;
}

.cardWide {
  grid-column: 1 / -1;
}

.metricsRow {
  display: flex;
  gap: 32px;
}

.metric {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

@media (max-width: 520px) {
  .metricsRow {
    flex-direction: column;
    gap: 14px;
  }
}

/* ── Estados de carga y error ──────────────────────────────────────────── */
.msg {
  font-size: var(--bw-size-body);
  color: var(--bw-steel-mist);
  margin-top: 8px;
}

.error {
  font-size: var(--bw-size-body);
  color: var(--bw-error-text);
  margin-top: 8px;
}

