import { useEffect, useRef, useState } from 'react';
import { errorMessage, type MemberProfile } from '../../lib/session';
import {
  dateLabel,
  fetchPanelSummary,
  latestOfferLine,
  latestQueryLine,
  metricLabel,
  subtitleLabel,
  type PanelSummary,
} from '../../lib/panel';
import styles from './Panel.module.css';

const EYEBROW = 'Panel · PANEL-01';
const TITLE = 'Mi Panel';
const LOADING = 'Cargando el panel…';

/**
 * PANEL-01 · Mi Panel (dashboard de entrada tras login).
 *
 * Contrato: `openspec/design-gui/specs y html aprobados/specs/Rinworld_spec_PANEL-01.md`
 * y su HTML aprobado.
 *
 * =============================================================================
 * DECISIONES QUE LA SPEC NO PODÍA TOMAR
 * =============================================================================
 *
 * 1 · EL EFECTO DE CARGA NO DEPENDE DE `now`, SOLO DE `orgId`.
 *    `now` es una prop inyectable para tests. Si el padre pasa un `Date` nuevo
 *    en cada render con el MISMO instante, la consulta no debe relanzarse:
 *    sería un falso positivo — la identidad del reloj cambió, pero la hora no.
 *    Se guarda el `now` más reciente en una ref y el efecto solo se ejecuta al
 *    montar o al cambiar de organización. El reloj se lee en el momento de la
 *    carga, no se observa.
 *
 * 2 · LAS TRES MÉTRICAS SIN FUENTE VAN CON GUIÓN, NO CON CERO.
 *    Visitas (30d), hilos sin leer y favoritos del mes devuelven `null` en
 *    `fetchPanelSummary` (ver la cabecera de `lib/panel.ts`). Un 0 afirmaría
 *    "he mirado y no hay ninguno"; el guion dice "esto todavía no se mide".
 *    El guion sale de `metricLabel(null)`, nunca de un '—' escrito a mano.
 *
 * 3 · LA TARJETA DE FAVORITOS NO NAVEGA.
 *    La spec §4.6 la manda a DIR-01/DIR-02, que están fuera del MVP. El botón
 *    se pinta deshabilitado — mismo criterio que el botón de subida de INV-01 —
 *    porque un botón que finge navegar engana más que un botón apagado.
 *
 * 4 · EL HOVER DE LAS TARJETAS USA --bw-focus-halo.
 *    El HTML aprobado pide una sombra de elevación (0 4px 14px rgba(27,37,55,.08))
 *    que no tiene token. --bw-focus-halo es la única sombra del sistema, y el
 *    cambio de borde a --bw-line-steel-strong hace el resto del realce.
 */

export function Panel({
  profile,
  now,
  onNavigate,
}: {
  profile: MemberProfile;
  now?: Date;
  onNavigate: (screen: 'Vendiendo' | 'Comprando' | 'Inventario' | 'Hilos') => void;
}) {
  const [summary, setSummary] = useState<PanelSummary | null>(null);
  const [error, setError] = useState<string | null>(null);

  /* Decisión 1: la ref siempre apunta al `now` más reciente, pero el efecto no
     se relanza por eso. La carga se dispara solo al montar o al cambiar orgId. */
  const nowRef = useRef(now);
  nowRef.current = now;

  useEffect(() => {
    let cancelled = false;
    setSummary(null);
    setError(null);

    const fetchNow = nowRef.current;
    const query = fetchNow ? { orgId: profile.orgId, now: fetchNow } : { orgId: profile.orgId };
    fetchPanelSummary(query)
      .then((s) => {
        if (!cancelled) setSummary(s);
      })
      .catch((e) => {
        if (!cancelled) setError(`No se ha podido cargar el panel: ${errorMessage(e)}`);
      });

    return () => {
      cancelled = true;
    };
  }, [profile.orgId]);

  return (
    <div className={styles.body}>
      <div className={styles.eyebrow}>{EYEBROW}</div>
      <h1 className={styles.title}>{TITLE}</h1>
      <p className={styles.sub}>{subtitleLabel(profile.fullName, profile.email, now)}</p>

      {error !== null ? (
        <div className={styles.error} role="alert" data-testid="panel-error">
          {error}
        </div>
      ) : summary === null ? (
        <p className={styles.msg} aria-busy="true" data-testid="panel-loading">
          {LOADING}
        </p>
      ) : (
        <div className={styles.grid}>
          {/* 4.1 · Ofertas → VND-01 (Vendiendo) */}
          <button
            type="button"
            className={styles.card}
            onClick={() => onNavigate('Vendiendo')}
            data-testid="panel-offers"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-tag" />
              </div>
              <div className={styles.cardTitle}>Ofertas</div>
            </div>
            <div className={styles.num}>{metricLabel(summary.offers.pending)}</div>
            <div className={styles.label}>pendientes de respuesta</div>
            <div className={styles.invLine}>{latestOfferLine(summary.offers.latest)}</div>
          </button>

          {/* 4.2 · Consultas → SRCH-01 (Comprando) */}
          <button
            type="button"
            className={styles.card}
            onClick={() => onNavigate('Comprando')}
            data-testid="panel-queries"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-search" />
              </div>
              <div className={styles.cardTitle}>Consultas</div>
            </div>
            <div className={styles.num}>{metricLabel(summary.queries.unanswered)}</div>
            <div className={styles.label}>sin respuesta</div>
            <div className={styles.invLine}>{latestQueryLine(summary.queries.latest)}</div>
          </button>

          {/* 4.3 · Inventario → INV-01 */}
          <button
            type="button"
            className={styles.card}
            onClick={() => onNavigate('Inventario')}
            data-testid="panel-inventory"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-package" />
              </div>
              <div className={styles.cardTitle}>Inventario</div>
            </div>
            <div className={styles.invLine}>
              <b>{summary.inventory.published.toLocaleString('es-ES')}</b> líneas publicadas
            </div>
            <div className={styles.invLine}>
              Última publicación: {dateLabel(summary.inventory.lastUploadAt)}
            </div>
            <div className={styles.invLine}>
              <b>{metricLabel(summary.inventory.visits)}</b> visitas (30d)
            </div>
          </button>

          {/* 4.4 · Hilos → MSG-01 */}
          <button
            type="button"
            className={styles.card}
            onClick={() => onNavigate('Hilos')}
            data-testid="panel-threads"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-messages" />
              </div>
              <div className={styles.cardTitle}>Hilos</div>
            </div>
            <div className={styles.num}>{metricLabel(summary.threads.unread)}</div>
            <div className={styles.label}>con mensajes sin leer</div>
            {/* threads.latest es null por diseño (F-027 a): no hay fuente de
                "mensajes no leídos". Línea con guion, igual que la métrica. */}
            <div className={styles.invLine}>—</div>
          </button>

          {/* 4.5 · Resumen mes → VND-01 (ancho completo) */}
          <button
            type="button"
            className={`${styles.card} ${styles.cardWide}`}
            onClick={() => onNavigate('Vendiendo')}
            data-testid="panel-month"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-circle-check" />
              </div>
              <div className={styles.cardTitle}>Resumen mes</div>
            </div>
            <div className={styles.metricsRow}>
              <div className={styles.metric}>
                <div className={styles.num}>{metricLabel(summary.month.acceptedOffers)}</div>
                <div className={styles.label}>Ofertas Aceptadas</div>
              </div>
              <div className={styles.metric}>
                <div className={styles.num}>{metricLabel(summary.month.madeOffers)}</div>
                <div className={styles.label}>Ofertas Realizadas</div>
              </div>
              <div className={styles.metric}>
                <div className={styles.num}>{metricLabel(summary.month.receivedQueries)}</div>
                <div className={styles.label}>Consultas Realizadas</div>
              </div>
            </div>
          </button>

          {/* 4.6 · Favoritos recibidos — DIR-01/DIR-02 fuera del MVP: no navega.
              Deshabilitado, no ausente: el diseño aprobado lo pide, y un botón
              que finge navegar engana más que un botón apagado. */}
          <button
            type="button"
            className={styles.card}
            disabled
            title="El directorio (DIR-01/DIR-02) está fuera del alcance del MVP"
            data-testid="panel-favorites"
          >
            <div className={styles.cardHead}>
              <div className={`${styles.ico} ${styles.icoBlue}`} aria-hidden="true">
                <i className="ti ti-star" />
              </div>
              <div className={styles.cardTitle}>Favoritos recibidos</div>
            </div>
            <div className={styles.num}>{metricLabel(summary.favorites.monthly)}</div>
            <div className={styles.label}>organizaciones te añadieron a favoritos este mes</div>
          </button>
        </div>
      )}
    </div>
  );
}
